window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-00c12515b69cbfa5"]={"versions": [{"id": "FIG-00c12515b69cbfa5", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Prüfschritts „Read Length“ innerhalb der Funktion <code>E2E_P07Check()</code> gemäß AUTOSAR E2E-Protokoll (Profil 7). Das Diagramm beschreibt die Extraktion der Längenangabe aus dem empfangenen Datenstrom im Kontext der E2E-Bibliothek / des E2E-Schutzes.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Kontext-Element: Funktionsrahmen <code>E2E_P07Check()</code> mit Callout-Konnektor-Symbol (Loop/Sub-Activity).\n</li><li>Datenstrukturen &amp; Variablen:\n<ul class=\"fig-list\"><li>Byte-Array <code>Data[]</code> (Eingabepuffer der empfangenen Botschaft).\n</li><li>Offset-Index <code>Offset</code> (Offset des E2E-Headers im Datenstrom).\n</li><li>Lokale Variable <code>ReceivedLength</code> vom Basistyp <code>uint32</code>.\n</li></ul>\n</li><li>Steuerungselemente:\n<ul class=\"fig-list\"><li>Initialer Startknoten (Initial Node, ausgefüllter Kreis).\n</li><li>Einzelne Aktionsaktion / Ausführungsknoten (Action State): <code>Copy bytes Data[Offset+8...Offset+11] in Big Endian order to uint32 local variable ReceivedLength</code>.\n</li><li>Aktivitätsendknoten (Activity Final Node, konzentrischer Doppelkreis mit gefülltem inneren Kreis).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Startknoten bei Aufruf des Prüfschritts „Read Length“ innerhalb von <code>E2E_P07Check()</code>.\n</li><li>Unmittelbarer Kontrollflussübergang zur Aktion: Aus dem Array <code>Data</code> werden genau vier aufeinanderfolgende Bytes ab der Adresse <code>Offset + 8</code> bis <code>Offset + 11</code> ausgelesen und in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in die lokale 32-Bit-Ganzzahlvariable <code>ReceivedLength</code> kopiert.\n</li><li>Kontrollflussübergang zum Aktivitätsendknoten und Beendigung des Schritts zur Weitergabe der extrahierten Länge an die nachfolgenden Validierungsschritte.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Anforderung [PRS_E2E_00497] bezüglich RS_E2E_08539: Für Profil 7 ist das Längenfeld zwingend 4 Bytes (32 Bit) breit und liegt an den Byte-Offsets 8 bis 11 relativ zu <code>Offset</code>. Die Dekodierung hat strikt in Big-Endian-Reihenfolge zu erfolgen, unabhängig von der nativen Prozessor-Endianness der Zielplattform. Eine falsche Byte-Reihenfolge führt zu fehlerhafter Validierung der Nutzlänge.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ecc2a23cdaa4fc0d", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Prüfschritts „Read Length“ innerhalb der Funktion <code>E2E_P07Check()</code> gemäß AUTOSAR E2E-Protokoll (Profil 7). Das Diagramm beschreibt die Extraktion der Längenangabe aus dem empfangenen Datenstrom im Kontext der E2E-Bibliothek / des E2E-Schutzes.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Kontext-Element: Funktionsrahmen <code>E2E_P07Check()</code> mit Callout-Konnektor-Symbol (Loop/Sub-Activity).\n</li><li>Datenstrukturen &amp; Variablen:\n<ul class=\"fig-list\"><li>Byte-Array <code>Data[]</code> (Eingabepuffer der empfangenen Botschaft).\n</li><li>Offset-Index <code>Offset</code> (Offset des E2E-Headers im Datenstrom).\n</li><li>Lokale Variable <code>ReceivedLength</code> vom Basistyp <code>uint32</code>.\n</li></ul>\n</li><li>Steuerungselemente:\n<ul class=\"fig-list\"><li>Initialer Startknoten (Initial Node, ausgefüllter Kreis).\n</li><li>Einzelne Aktionsaktion / Ausführungsknoten (Action State): <code>Copy bytes Data[Offset+8...Offset+11] in Big Endian order to uint32 local variable ReceivedLength</code>.\n</li><li>Aktivitätsendknoten (Activity Final Node, konzentrischer Doppelkreis mit gefülltem inneren Kreis).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Startknoten bei Aufruf des Prüfschritts „Read Length“ innerhalb von <code>E2E_P07Check()</code>.\n</li><li>Unmittelbarer Kontrollflussübergang zur Aktion: Aus dem Array <code>Data</code> werden genau vier aufeinanderfolgende Bytes ab der Adresse <code>Offset + 8</code> bis <code>Offset + 11</code> ausgelesen und in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in die lokale 32-Bit-Ganzzahlvariable <code>ReceivedLength</code> kopiert.\n</li><li>Kontrollflussübergang zum Aktivitätsendknoten und Beendigung des Schritts zur Weitergabe der extrahierten Länge an die nachfolgenden Validierungsschritte.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Anforderung [PRS_E2E_00497] bezüglich RS_E2E_08539: Für Profil 7 ist das Längenfeld zwingend 4 Bytes (32 Bit) breit und liegt an den Byte-Offsets 8 bis 11 relativ zu <code>Offset</code>. Die Dekodierung hat strikt in Big-Endian-Reihenfolge zu erfolgen, unabhängig von der nativen Prozessor-Endianness der Zielplattform. Eine falsche Byte-Reihenfolge führt zu fehlerhafter Validierung der Nutzlänge.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-da2d41d7db338dbd", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Prüfschritts „Read Length“ innerhalb der Funktion <code>E2E_P07Check()</code> gemäß AUTOSAR E2E-Protokoll (Profil 7). Das Diagramm beschreibt die Extraktion der Längenangabe aus dem empfangenen Datenstrom im Kontext der E2E-Bibliothek / des E2E-Schutzes.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Kontext-Element: Funktionsrahmen <code>E2E_P07Check()</code> mit Callout-Konnektor-Symbol (Loop/Sub-Activity).\n</li><li>Datenstrukturen &amp; Variablen:\n<ul class=\"fig-list\"><li>Byte-Array <code>Data[]</code> (Eingabepuffer der empfangenen Botschaft).\n</li><li>Offset-Index <code>Offset</code> (Offset des E2E-Headers im Datenstrom).\n</li><li>Lokale Variable <code>ReceivedLength</code> vom Basistyp <code>uint32</code>.\n</li></ul>\n</li><li>Steuerungselemente:\n<ul class=\"fig-list\"><li>Initialer Startknoten (Initial Node, ausgefüllter Kreis).\n</li><li>Einzelne Aktionsaktion / Ausführungsknoten (Action State): <code>Copy bytes Data[Offset+8...Offset+11] in Big Endian order to uint32 local variable ReceivedLength</code>.\n</li><li>Aktivitätsendknoten (Activity Final Node, konzentrischer Doppelkreis mit gefülltem inneren Kreis).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Startknoten bei Aufruf des Prüfschritts „Read Length“ innerhalb von <code>E2E_P07Check()</code>.\n</li><li>Unmittelbarer Kontrollflussübergang zur Aktion: Aus dem Array <code>Data</code> werden genau vier aufeinanderfolgende Bytes ab der Adresse <code>Offset + 8</code> bis <code>Offset + 11</code> ausgelesen und in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in die lokale 32-Bit-Ganzzahlvariable <code>ReceivedLength</code> kopiert.\n</li><li>Kontrollflussübergang zum Aktivitätsendknoten und Beendigung des Schritts zur Weitergabe der extrahierten Länge an die nachfolgenden Validierungsschritte.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Anforderung [PRS_E2E_00497] bezüglich RS_E2E_08539: Für Profil 7 ist das Längenfeld zwingend 4 Bytes (32 Bit) breit und liegt an den Byte-Offsets 8 bis 11 relativ zu <code>Offset</code>. Die Dekodierung hat strikt in Big-Endian-Reihenfolge zu erfolgen, unabhängig von der nativen Prozessor-Endianness der Zielplattform. Eine falsche Byte-Reihenfolge führt zu fehlerhafter Validierung der Nutzlänge.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-00c12515b69cbfa5", "to": "FIG-ecc2a23cdaa4fc0d", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ecc2a23cdaa4fc0d", "to": "FIG-da2d41d7db338dbd", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
